import {loadRepairExams,loadRepairExamRetries,repairExamGrade} from './workshop-repair-exam-model.mjs';
import {repairExamTotal,repairExamMastery} from './workshop-repair-exam-history.mjs';
import {caseInfo} from './workshop-content.mjs';
import {alternate} from './workshop-challenges.mjs';
export function mountRepairExamHistory({language,busy,review,retry,cancel}){
 const root=document.createElement('section');root.id='repairExamHistory';root.className='challenge-panel';document.querySelector('main').append(root);
 const t=(es,en)=>language()==='es'?es:en,local=x=>x[language()];
 const faultName=r=>{const a=local(caseInfo[r.kind].options[({mechanics:'ground',electronics:'clipping',hydraulics:'leak',pneumatics:'restriction'})[r.kind]]),b=local(alternate[r.kind].label);return(r.fault.startsWith('intermittent-')?t('Intermitente: ','Intermittent: '):'')+(r.fault==='combined'?a+' + '+b:r.fault.endsWith('alternate')?b:a);};
 function render(){root.replaceChildren();const add=(tag,text,host=root)=>{const e=document.createElement(tag);e.textContent=text;host.append(e);return e;};add('h2',t('Historial de exámenes de reparación','Repair exam history'));if(busy()){add('p',t('El historial y las soluciones se ocultan durante el examen o reintento.','History and solutions are hidden during an exam or retry.'));const b=add('button',t('Abandonar intento y ver historial','Abandon attempt and view history'));b.onclick=cancel;return;}
 let exams=[],retries=[];try{exams=loadRepairExams(localStorage).sort((a,b)=>Date.parse(a.finished)-Date.parse(b.finished));retries=loadRepairExamRetries(localStorage);}catch{add('p',t('No se pudo leer el historial. No se modificaron los datos guardados.','Could not read history. Saved data was not modified.'));return;}
 add('p',t('Se conservan 25 exámenes y 100 reintentos en este navegador. Los reintentos son prácticas conocidas: no cambian la nota original ni demuestran dominio por sí solos.','This browser keeps 25 exams and 100 retries. Retries are known-case practice: they never change original scores or establish mastery by themselves.'));if(!exams.length){add('p',t('Termina un examen para comenzar tu historial.','Finish an exam to start your history.'));return;}
 add('h3',t('Compara tus notas','Compare your scores'));const chart=add('div','');chart.className='repair-weekly-plan';for(const e of exams){const card=add('article','',chart),score=repairExamTotal(e);add('p',new Date(e.finished).toLocaleString(language(),{timeZone:'America/Bogota'})+' · '+score+'/100',card);const meter=add('meter','',card);meter.min=0;meter.max=100;meter.value=score;meter.setAttribute('aria-label',score+'/100');}add('p',t('Los casos pueden variar entre exámenes; compara también cada configuración de fallo.','Cases can differ between exams; also compare each fault configuration.'));
 add('h3',t('Progreso por avería','Progress by fault'));for(const g of repairExamMastery(exams,retries)){const card=add('article','');card.className='repair-progress-card';add('h4',faultName(g),card);add('p',g.count+t(' casos de examen · primero ',' exam cases · first ')+g.first+'/100 · '+t('último ','latest ')+g.latest+'/100',card);add('strong',g.status==='early'?t('Datos iniciales: menos de tres casos','Early evidence: fewer than three cases'):g.status==='consistent'?t('Consistente: últimos tres casos perfectos y verificados','Consistent: last three cases perfect and verified'):t('Necesita repaso','Needs practice'),card);add('p',g.remaining+t(' causas sin resolver · ',' unresolved causes · ')+g.unnecessary+t(' intervenciones innecesarias · ',' unnecessary interventions · ')+g.missing+t(' casos sin pruebas completas',' cases with incomplete evidence'),card);if(g.retries.length)add('p',t('Reintentos separados: ','Separate retries: ')+g.retries.length+' · '+t('último ','latest ')+g.retries.at(-1).score+'/100',card);}
 add('h3',t('Revisar o repetir casos','Review or retry cases'));for(const e of [...exams].reverse()){const details=add('details','');add('summary',new Date(e.finished).toLocaleString(language(),{timeZone:'America/Bogota'})+' · '+repairExamTotal(e)+'/100',details);for(const [index,c]of e.cases.entries()){const card=add('article','',details);add('h4',local(caseInfo[c.repair.kind].title)+' · '+faultName(c.repair)+' · '+repairExamGrade(c).score+'/100',card);const b=add('button',t('Revisar pasos en 3D','Review steps in 3D'),card);b.dataset.archiveReview=e.id+':'+index;b.onclick=()=>review(e,index);if(repairExamGrade(c).score<100){const r=add('button',t('Reintentar este caso','Retry this case'),card);r.dataset.archiveRetry=e.id+':'+index;r.onclick=()=>retry(e,index);}}}
 }
 return {render};
}
